import {
  COMMENTERS_MESSAGE_FORM_SHOW,
  COMMENTERS_MESSAGE_FORM_HIDE

} from '../actions/commentersSearchActions';


export default function commentersMessageReducer(state, action) {
  
  switch(action.type) {

    case COMMENTERS_MESSAGE_FORM_SHOW:
      return {
        ...state,
        showCommentersMessageForm: true
      };
      
    case COMMENTERS_MESSAGE_FORM_HIDE:
      return {
        ...state,
        showCommentersMessageForm: false
      };
      
      
    case COMMENTERS_MESSAGE_SUBMITTED:
      return {
        ...state,
            showCommentersTable: false,
            showCommentersMessageSubmitButton: false,
            showCommentersMessageSubmitLoadingButton: true,
            enableCommentersMessageInput: false,
            showErrorAlert: false,
            showSuccessAlert: false,
            showInfoAlert: false
        
      };
      
      
    case COMMENTERS_MESSAGE_NO_RESULTS:
        console.log("sc login error - reducer");
        //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none';
      return {
        ...state,
        errorAlertText: '',
        errorAlertLinkText: '',
        showInfoAlert: false,
        showSuccessAlert: true,
        showErrorAlert: true,
        showCommentersMessageSubmitButton: true,
        showCommentersMessageSubmitLoadingButton: false,
        enableCommentersMessageFormInputs: true,
        showCommentersTable: true,
        successAlertText: "But there were no commenters found for this track."
        
 
      };
      
    case COMMENTERS_MESSAGE_OTHER_ERROR:
         console.log("sc cookie error - reducer");
      return {
        ...state,
        showInfoAlert: false,
        showLoginForm: false,
        errorAlertText: "Something went wrong. Please contact support.",
        errorAlertLinkText: '',
        showErrorAlert: true,
        showCommentersMessageSubmitLoadingButton: false
      };
      
      
    case COMMENTERS_MESSAGE_SUCCESS:
         console.log("sc commentersMessage success - reducer");
         //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none'
      return {
        ...state,
        showInfoAlert: false,
        showErrorAlert: false,
        showCommentersMessageSubmitLoadingButton: false,
        showCommentersMessageSubmitButton: true,
        enableCommentersMessageSubmitButton: true, 
        enableCommentersMessageInput: true,
        commenterData: action.commenterData,
        showCommentersTable: true,
        successAlertText: "Found " + action.commenterData.length + ' commenters.',
        
                
            /*this.setState({showSuccessAlert: true},()=>{
            window.setTimeout(()=>{
              this.setState({showSuccessAlert: false})
            },4000)*/

        //successAlertText: "You're now logged in!"
    
      };
      
    
    default:
      // ALWAYS have a default case in a reducer
      return state;
  }
}
